void my_aes_cbc_128_pkcs7_padding_encrypt(const uint8_t* plain_text, uint8_t* cipher_text, const uint8_t* user_key, uint8_t* iv, uint32_t rounds){
    AES_KEY aesKey;
    aes_set_encrypt_key(&aesKey, user_key, 16);
    aes_cbc_encrypt(&aesKey, iv, plain_text, rounds, cipher_text);
}



void my_aes_cbc_128_encrypt(const uint8_t* plain_text, uint8_t* cipher_text, const uint8_t* user_key, uint8_t* iv, uint32_t src_len, uint32_t real_len){
    uint8_t * real_src = (uint8_t*) malloc(real_len);
    memcpy(real_src, plain_text, src_len);
    memset(real_src+ src_len, real_len - src_len, real_len - src_len);
    my_aes_cbc_128_pkcs7_padding_encrypt(real_src, cipher_text, user_key, iv, real_len >> 4);
}


void encrypt_test(const uint8_t *plain_text, uint32_t plain_text_len, const uint8_t *user_key, uint8_t *iv) {
    size_t out_len = (plain_text_len + 0x10) & 0xfffffff0;
    uint8_t *cipher_text = (uint8_t *) malloc(out_len);
    my_aes_cbc_128_encrypt(plain_text, cipher_text, user_key, iv, plain_text_len, out_len);
    LOGI("encrypt success");
}


