void func_callback(int sig, siginfo_t *info, void *ucontext){
    LOGI("receive target signal %d from %d", sig, info->si_pid);
    LOGI("🔥 breakpoint hit!");
    LOGI("addr: 0x%lx", info->si_ptr);
    ucontext_t *ctx = (ucontext_t *)ucontext;
    greg_t *regs = ctx->uc_mcontext.regs;
    uint64_t ar0 = regs[0];
    uint64_t ar1 = regs[1];
    uint64_t ar2 = regs[2];
    uint64_t ar3 = regs[3];


    printf("arg1 : %lx\n", ar0);
    printf("arg2 : %lx\n", ar1);
    printf("arg3 : %lx\n", ar2);
    printf("arg4 : %lx\n", ar3);

    hexdump((void *)ar0, 0x20);
    hexdump((void *)ar3, 0x10);
}




void set_signal_handle(){
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_sigaction = func_callback;
    sa.sa_flags = SA_SIGINFO;
//   自定义的信号信息
    int signal_info_res = sigaction(MY_SIG, &sa, NULL);
    sigset_t set;
    sigemptyset(&set);
    sigaddset(&set, MY_SIG);
    sigprocmask(SIG_UNBLOCK, &set, NULL);
    LOGI("register signal handler res %d", signal_info_res);
    LOGI("current pid is %d", getpid());
}



void signal_handle(){
    struct my_task t;
    t.address = (uint64_t)encrypt_test;
    t.type = 1;
    LOGI("target function address %p ", encrypt_test);
    set_signal_handle();
    prctl(PR_REGIS_HW_BP, &t, 0, 0, 0);
}



static JNINativeMethod nativeMethod[] = {
        {"encrypt", "()V", (void *)native_encrypt}
};

static int registerNativeMethod(JNIEnv *env, const char *class_name) {
    int result = -1;

    jclass class_text = (*env)->FindClass(env, class_name);
    if ((*env)->RegisterNatives(env, class_text, nativeMethod,
                                sizeof(nativeMethod) / sizeof(nativeMethod[0])) == JNI_OK) {
        result = 0;
        return result;
    }
    return result;
}


jint JNI_OnLoad(JavaVM *vm, void *reserved) {
    JNIEnv *env = NULL;
    int result = -1;
    if ((*vm)->GetEnv(vm, (void **) &env, JNI_VERSION_1_6) == JNI_OK) {
        if (registerNativeMethod(env, "com/example/encrypt/MainActivity") == JNI_OK) {
            signal_handle();
            return JNI_VERSION_1_6;
        }
        return result;
    }
    return result;
}
